Here's a sharded concurrent map using `RwLock`. The keyspace is split across N shards (power of two) so operations on different keys typically proceed in parallel, and reads on the same shard can run concurrently.

```rust
use std::borrow::Borrow;
use std::collections::hash_map::RandomState;
use std::collections::HashMap;
use std::fmt;
use std::hash::{BuildHasher, Hash, Hasher};
use std::sync::{RwLock, RwLockReadGuard, RwLockWriteGuard};

/// A thread-safe concurrent map using `RwLock`-protected shards.
///
/// Keys are routed to one of `N` shards by hash. Each shard is an independent
/// `HashMap` behind its own `RwLock`, so disjoint keys rarely contend and
/// readers on the same shard run in parallel.
pub struct ShardedMap<K, V, S = RandomState> {
    shards: Box<[RwLock<HashMap<K, V, S>>]>,
    hasher: S,
    shard_mask: usize,
}

fn default_shard_count() -> usize {
    let cpus = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    (cpus * 4).next_power_of_two()
}

impl<K, V> ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    /// Creates a map with a sensible default shard count (~4x CPU cores).
    pub fn new() -> Self {
        Self::with_shards(default_shard_count())
    }

    /// Creates a map with at least `shards` shards (rounded up to a power of two).
    pub fn with_shards(shards: usize) -> Self {
        Self::with_shards_and_hasher(shards, RandomState::new())
    }
}

impl<K, V, S> ShardedMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Clone,
{
    pub fn with_shards_and_hasher(shards: usize, hasher: S) -> Self {
        let shards = shards.max(1).next_power_of_two();
        let mut v = Vec::with_capacity(shards);
        for _ in 0..shards {
            v.push(RwLock::new(HashMap::with_hasher(hasher.clone())));
        }
        Self {
            shards: v.into_boxed_slice(),
            hasher,
            shard_mask: shards - 1,
        }
    }

    pub fn shard_count(&self) -> usize {
        self.shards.len()
    }

    #[inline]
    fn shard_index<Q>(&self, key: &Q) -> usize
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let mut h = self.hasher.build_hasher();
        key.hash(&mut h);
        (h.finish() as usize) & self.shard_mask
    }

    // Recover from poisoning so a panic in user code doesn't permanently
    // break the map. Callers see a (possibly inconsistent) inner state.
    #[inline]
    fn read_shard(&self, idx: usize) -> RwLockReadGuard<'_, HashMap<K, V, S>> {
        self.shards[idx].read().unwrap_or_else(|e| e.into_inner())
    }

    #[inline]
    fn write_shard(&self, idx: usize) -> RwLockWriteGuard<'_, HashMap<K, V, S>> {
        self.shards[idx].write().unwrap_or_else(|e| e.into_inner())
    }

    pub fn insert(&self, key: K, value: V) -> Option<V> {
        let idx = self.shard_index(&key);
        self.write_shard(idx).insert(key, value)
    }

    pub fn remove<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let idx = self.shard_index(key);
        self.write_shard(idx).remove(key)
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let idx = self.shard_index(key);
        self.read_shard(idx).contains_key(key)
    }

    /// Returns a clone of the value when `V: Clone`.
    pub fn get<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        V: Clone,
    {
        let idx = self.shard_index(key);
        self.read_shard(idx).get(key).cloned()
    }

    /// Borrowed read access to the value via a closure. The shard's read
    /// lock is held only for the duration of `f`.
    pub fn with<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&V) -> R,
    {
        let idx = self.shard_index(key);
        self.read_shard(idx).get(key).map(f)
    }

    /// Borrowed mutable access via a closure. Holds the shard's write lock.
    pub fn with_mut<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&mut V) -> R,
    {
        let idx = self.shard_index(key);
        self.write_shard(idx).get_mut(key).map(f)
    }

    /// Atomically update or insert: applies `f` to the existing value if
    /// present, otherwise inserts `default`.
    pub fn upsert<F>(&self, key: K, default: V, f: F)
    where
        F: FnOnce(&mut V),
    {
        let idx = self.shard_index(&key);
        self.write_shard(idx)
            .entry(key)
            .and_modify(f)
            .or_insert(default);
    }

    /// Get-or-insert with a lazily computed default. Returns a clone.
    pub fn get_or_insert_with<F>(&self, key: K, default: F) -> V
    where
        F: FnOnce() -> V,
        V: Clone,
    {
        let idx = self.shard_index(&key);
        self.write_shard(idx).entry(key).or_insert_with(default).clone()
    }

    pub fn len(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.read().unwrap_or_else(|e| e.into_inner()).len())
            .sum()
    }

    pub fn is_empty(&self) -> bool {
        self.shards
            .iter()
            .all(|s| s.read().unwrap_or_else(|e| e.into_inner()).is_empty())
    }

    pub fn clear(&self) {
        for shard in self.shards.iter() {
            shard.write().unwrap_or_else(|e| e.into_inner()).clear();
        }
    }

    /// Snapshot all entries by cloning. Each shard is briefly locked in turn,
    /// so the snapshot is not a globally consistent point-in-time view.
    pub fn snapshot(&self) -> Vec<(K, V)>
    where
        K: Clone,
        V: Clone,
    {
        let mut out = Vec::with_capacity(self.len());
        for shard in self.shards.iter() {
            let g = shard.read().unwrap_or_else(|e| e.into_inner());
            out.extend(g.iter().map(|(k, v)| (k.clone(), v.clone())));
        }
        out
    }
}

impl<K, V> Default for ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<K, V, S> fmt::Debug for ShardedMap<K, V, S> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ShardedMap")
            .field("shards", &self.shards.len())
            .finish_non_exhaustive()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use std::thread;

    #[test]
    fn basic_ops() {
        let map: ShardedMap<String, i32> = ShardedMap::new();
        assert_eq!(map.insert("a".into(), 1), None);
        assert_eq!(map.insert("a".into(), 2), Some(1));
        assert_eq!(map.get("a"), Some(2));
        assert!(map.contains_key("a"));
        assert_eq!(map.remove("a"), Some(2));
        assert!(map.is_empty());
    }

    #[test]
    fn upsert_counts() {
        let map: ShardedMap<&str, u64> = ShardedMap::new();
        for _ in 0..5 {
            map.upsert("hits", 1, |v| *v += 1);
        }
        assert_eq!(map.get("hits"), Some(5));
    }

    #[test]
    fn concurrent_disjoint_inserts() {
        let map = Arc::new(ShardedMap::<u64, u64>::with_shards(16));
        let handles: Vec<_> = (0..8u64)
            .map(|t| {
                let m = map.clone();
                thread::spawn(move || {
                    for i in 0..1000u64 {
                        m.insert(t * 1000 + i, i);
                    }
                })
            })
            .collect();
        for h in handles { h.join().unwrap(); }
        assert_eq!(map.len(), 8000);
    }

    #[test]
    fn concurrent_shared_counter() {
        let map = Arc::new(ShardedMap::<&'static str, u64>::new());
        let handles: Vec<_> = (0..8)
            .map(|_| {
                let m = map.clone();
                thread::spawn(move || {
                    for _ in 0..1000 {
                        m.upsert("count", 1, |v| *v += 1);
                    }
                })
            })
            .collect();
        for h in handles { h.join().unwrap(); }
        assert_eq!(map.get("count"), Some(8000));
    }
}
```

A few notes on the design choices:

- **Shard count is rounded up to a power of two** so we can replace `hash % N` with `hash & (N - 1)`, which is faster and removes a branch.
- **`RwLock` over `Mutex`** because read-heavy workloads benefit from concurrent readers. Swap to `parking_lot::RwLock` for faster, non-poisoning locks if you want to drop the `unwrap_or_else(into_inner)` recovery dance.
- **Poison recovery** via `into_inner` keeps the map usable if a user closure panics inside `with_mut` or `upsert`. The data structure invariants stay valid because `HashMap`'s own state is never left torn by a panic between shard operations.
- **`with` / `with_mut` closures** avoid forcing `V: Clone` for read access. Returning a guard would tie the lifetime to the map and is awkward across closure boundaries; the closure pattern is simpler and bounds the lock-hold time clearly.
- **The shard hasher and inner `HashMap` hashers share a `BuildHasher`**, which means hashing happens twice (once for shard selection, once inside `HashMap`). That is the price of leaning on `std::HashMap`. If you need to avoid it, you can switch to `hashbrown::raw::RawTable` and reuse the hash, but it's a meaningful jump in complexity.

Drop-in usage:

```rust
let map: Arc<ShardedMap<String, u64>> = Arc::new(ShardedMap::new());
map.insert("requests".into(), 0);
map.upsert("requests".into(), 1, |v| *v += 1);
```
